{"packet_id":"D040-01","doc_id":"D040","jurisdiction":"Los Angeles, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Just Cause for Eviction Ordinance (JCO)","requirement":"Landlords may terminate a tenancy only for the ordinance's just causes and must pay relocation assistance for no-fault evictions; since March 27, 2023, a tenant may not be evicted for non-payment unless the arrears exceed the Fair Market Rent for the unit's bedroom size.","key_value":null,"coverage_conditions":"Most residential properties in the City of Los Angeles not regulated by the RSO; tenant must have lived in the unit at least six months or the original lease must have expired, whichever comes first.","applicability":{"conditions":[{"type":"other","text":"Units already regulated by the City's Rent Stabilization Ordinance"}],"per_tenancy":"Tenant has lived in the same unit at least six months or the original lease expired, whichever comes first.","coverage_quotes":["The JCO covers most residential properties in the City of Los Angeles that are not regulated by the City’s Rent Stabilization Ordinance (RSO).","In order to apply to a tenancy, it requires that the tenant either has lived in the same unit for at least six months or that their original lease expired, whichever comes first."]},"exemptions":"Transient hotels, licensed care facilities, fraternity or sorority houses, owner's roommate, cooperatives under certain circumstances, some non-profit facilities for the homeless or short-term substance-abuse treatment centers, and some properties owned by HACLA or the government.","penalty":null,"effective_date":null,"valid_through":null,"citation":"Los Angeles Just Cause Ordinance (L.A.M.C. §165.00 et seq.)","quoted_span":"It prohibits terminations of tenancies without just cause and requires relocation assistance for no-fault evictions.","interaction":"Does not regulate rent increases; state law AB 1482 may regulate rent amounts in buildings older than 15 years.","relations":[],"confidence":0.75,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D040-01","doc_id":"D040","jurisdiction":"CA","category":"rent_increase_limits","lifecycle":"enacted","title":"California Tenant Protection Act (AB 1482) annual rent cap","requirement":"Annual rent increases are capped at 5% plus the regional cost-of-living change, or 10%, whichever is lower; from August 1, 2024 to July 31, 2025 the maximum allowable increase is 8.9%.","key_value":"5% + CPI, max 10%; 8.9% (Aug 1, 2024–Jul 31, 2025)","coverage_conditions":"Buildings older than 15 years; units built within the last 15 years, deed-restricted affordable units, a two-unit owner-occupied property, certain dormitories, qualifying single-family homes and condominiums, and units under the City's RSO are exempt.","applicability":{"conditions":[{"type":"built_within_years","role":"exempt","years":15,"basis":"construction"},{"type":"owner","role":"exempt","who":"owner-occupied","unit_limit":2},{"type":"other","text":"Units restricted by deed or recorded document limiting affordability to low- or moderate-income households"},{"type":"other","text":"Units already subject to the City's Rent Stabilization Ordinance"},{"type":"other","text":"Single-family homes and condominiums not owned by a trust, corporation or corporate LLC, where the tenant got the required written notice"}],"per_tenancy":null,"coverage_quotes":["may regulate the rent amount in buildings that are older than 15 years old.","Units that were constructed within the last 15 years","Units that are already subject to the City’s RSO."]},"exemptions":"Units constructed in the last 15 years; units restricted by deed or recorded document limiting affordability to low- or moderate-income households; certain dormitories; a two-unit property with the second unit owner-occupied for the whole tenancy; qualifying single-family homes and condominiums; units already under the City's RSO.","penalty":null,"effective_date":"2024-08-01","valid_through":"2025-07-31","citation":"Cal. Civ. Code § 1947.12","quoted_span":"Effective August 1, 2024 to July 31, 2025, the maximum allowable increase is 8.9%.","interaction":null,"relations":[],"confidence":0.75,"conflict_flag":false,"conflict_note":null}
